<?php
if((string)($_GET['view']??'')==='finance'&&role_can_access_page($user['role'],'fees')){require __DIR__.'/finance_reports.php';return;}
if(!in_array($user['role'],['Administrator','Head','Teacher'],true)){require __DIR__.'/finance_reports.php';return;}
$pdo=db();$canManage=in_array($user['role'],['Administrator','Head'],true);

 $termRows=$pdo->query('SELECT id,academic_year,term_number,name,starts_on,ends_on,is_current FROM school_terms ORDER BY is_current DESC,academic_year DESC,term_number DESC')->fetchAll();$termId=filter_var($_GET['term_id']??null,FILTER_VALIDATE_INT);if(!$termId)foreach($termRows as $t)if($t['is_current']){$termId=(int)$t['id'];break;}if(!$termId&&$termRows)$termId=(int)$termRows[0]['id'];$term=null;foreach($termRows as $t)if((int)$t['id']===$termId)$term=$t;
 $classSql='SELECT c.id,c.form_level,c.stream,c.academic_year,c.class_teacher_id FROM class_groups c';$classParams=[];if($user['role']==='Teacher'){$classSql.=' WHERE c.class_teacher_id=:class_teacher OR EXISTS (SELECT 1 FROM class_subjects cs WHERE cs.class_id=c.id AND cs.teacher_id=:subject_teacher)';$classParams=['class_teacher'=>$user['id'],'subject_teacher'=>$user['id']];}$classSql.=' ORDER BY c.academic_year DESC,c.form_level,c.stream';$classStmt=$pdo->prepare($classSql);$classStmt->execute($classParams);$classRows=$classStmt->fetchAll();$classId=filter_var($_GET['class_id']??null,FILTER_VALIDATE_INT);if(!$classId&&$classRows)$classId=(int)$classRows[0]['id'];$class=null;foreach($classRows as $c)if((int)$c['id']===$classId)$class=$c;
 $studentId=filter_var($_GET['student_id']??null,FILTER_VALIDATE_INT);$roster=[];$attendanceRows=[];$results=[];$reportStudent=null;$reportComments=null;$scale=null;$attendance=['Present'=>0,'Absent'=>0,'Late'=>0,'Excused'=>0];$overallObtained=0.0;$overallPossible=0.0;$missingMarks=0;
 if($class&&$term&&(int)$class['academic_year']===(int)$term['academic_year']){
  $rosterStmt=$pdo->prepare("SELECT DISTINCT s.id,s.admission_no,s.first_name,s.last_name,s.sex,e.form_level,e.stream FROM students s JOIN student_enrolments e ON e.student_id=s.id WHERE e.academic_year=:year AND e.form_level=:form AND COALESCE(e.stream,'')=:stream AND e.start_date<=:term_end AND (e.end_date IS NULL OR e.end_date>=:term_start) ORDER BY s.last_name,s.first_name");$rosterStmt->execute(['year'=>$term['academic_year'],'form'=>$class['form_level'],'stream'=>$class['stream'],'term_end'=>$term['ends_on'],'term_start'=>$term['starts_on']]);$roster=$rosterStmt->fetchAll();
  if($studentId){foreach($roster as $candidate)if((int)$candidate['id']===$studentId)$reportStudent=$candidate;}
  if(!$reportStudent){$attendanceStmt=$pdo->prepare("SELECT s.id,s.admission_no,s.first_name,s.last_name,SUM(a.status='Present') AS present_count,SUM(a.status='Absent') AS absent_count,SUM(a.status='Late') AS late_count,SUM(a.status='Excused') AS excused_count FROM (SELECT DISTINCT st.id,st.admission_no,st.first_name,st.last_name FROM students st JOIN student_enrolments e ON e.student_id=st.id WHERE e.academic_year=:year AND e.form_level=:form AND COALESCE(e.stream,'')=:stream AND e.start_date<=:term_end AND (e.end_date IS NULL OR e.end_date>=:term_start)) s LEFT JOIN attendance a ON a.student_id=s.id AND a.attendance_date BETWEEN :start_date AND :end_date GROUP BY s.id,s.admission_no,s.first_name,s.last_name ORDER BY s.last_name,s.first_name");$attendanceStmt->execute(['year'=>$term['academic_year'],'form'=>$class['form_level'],'stream'=>$class['stream'],'term_end'=>$term['ends_on'],'term_start'=>$term['starts_on'],'start_date'=>$term['starts_on'],'end_date'=>$term['ends_on']]);$attendanceRows=$attendanceStmt->fetchAll();}
  if($reportStudent){$level=(int)$class['form_level']<=4?'O-Level':'A-Level';$scaleStmt=$pdo->prepare("SELECT id,name FROM grading_scales WHERE level=:level AND active=1 ORDER BY id DESC LIMIT 1");$scaleStmt->execute(['level'=>$level]);$scale=$scaleStmt->fetch()?:null;$bands=[];if($scale){$bandStmt=$pdo->prepare('SELECT grade,lower_percentage,upper_percentage,description FROM grading_bands WHERE scale_id=:id ORDER BY lower_percentage DESC');$bandStmt->execute(['id'=>$scale['id']]);$bands=$bandStmt->fetchAll();}
   $resultSql="SELECT s.id AS subject_id,s.subject_code,s.subject_name,COUNT(a.id) AS assessment_count,SUM(m.mark_status IS NOT NULL) AS entered_count,SUM(m.mark_status='Absent') AS absent_count,SUM(m.mark_status='Exempt') AS exempt_count,SUM(CASE WHEN m.mark_status='Scored' THEN m.mark ELSE 0 END) AS obtained,SUM(CASE WHEN m.mark_status='Scored' THEN a.max_mark ELSE 0 END) AS possible FROM class_subjects cs JOIN subjects s ON s.id=cs.subject_id AND s.active=1 LEFT JOIN assessments a ON a.class_id=cs.class_id AND a.subject_id=cs.subject_id AND a.term_id=:term LEFT JOIN assessment_marks m ON m.assessment_id=a.id AND m.student_id=:student WHERE cs.class_id=:class GROUP BY s.id,s.subject_code,s.subject_name ORDER BY s.subject_name";$resultStmt=$pdo->prepare($resultSql);$resultStmt->execute(['term'=>$termId,'student'=>$studentId,'class'=>$classId]);$results=$resultStmt->fetchAll();foreach($results as &$r){$r['obtained']=(float)$r['obtained'];$r['possible']=(float)$r['possible'];$r['percentage']=$r['possible']>0?round($r['obtained']/$r['possible']*100,2):null;$r['grade']=null;$r['band_description']=null;if($r['percentage']!==null)foreach($bands as $b)if($r['percentage']>=(float)$b['lower_percentage']&&$r['percentage']<=(float)$b['upper_percentage']){$r['grade']=$b['grade'];$r['band_description']=$b['description'];break;}$overallObtained+=$r['obtained'];$overallPossible+=$r['possible'];$missingMarks+=max(0,(int)$r['assessment_count']-(int)$r['entered_count']);}unset($r);
   $att=$pdo->prepare("SELECT status,COUNT(*) AS total FROM attendance WHERE student_id=:student AND attendance_date BETWEEN :start AND :end GROUP BY status");$att->execute(['student'=>$studentId,'start'=>$term['starts_on'],'end'=>$term['ends_on']]);foreach($att->fetchAll() as $ar)$attendance[$ar['status']]=(int)$ar['total'];$commentStmt=$pdo->prepare('SELECT teacher_comment,head_comment,updated_at FROM term_report_comments WHERE student_id=:student AND term_id=:term');$commentStmt->execute(['student'=>$studentId,'term'=>$termId]);$reportComments=$commentStmt->fetch()?:['teacher_comment'=>'','head_comment'=>'','updated_at'=>null];
  }
 }
?>
<?php if(role_can_access_page($user["role"],"fees")): ?><div class="settings-tabs"><a class="selected" href="?page=reports&view=academic">Academic reports</a><a href="?page=reports&view=finance">Finance report</a></div><?php endif; ?><div class="page-heading"><div><div class="eyebrow">LEARNER PROGRESS</div><h1>Academic report cards</h1><p class="subheading">Term marks, configurable school grades, attendance and school comments.</p></div><?php if($reportStudent): ?><button class="primary-button no-print" onclick="window.print()">Print report card</button><?php endif; ?></div>
<?php if(!$termRows||!$classRows): ?><section class="panel empty-state"><h2>Set up the academic calendar and classes</h2><p>Create terms, class groups and subject allocations before preparing report cards.</p><a class="primary-button" href="?page=academics&tab=terms">Configure academics</a></section><?php else: ?>
<form method="get" class="report-filter no-print"><input type="hidden" name="page" value="reports"><label>Term<select name="term_id" required><?php foreach($termRows as $t): ?><option value="<?= (int)$t['id'] ?>" <?= $termId===(int)$t['id']?'selected':'' ?>><?= h($t['name']) ?> · <?= (int)$t['academic_year'] ?></option><?php endforeach; ?></select></label><label>Class<select name="class_id" required><?php foreach($classRows as $c): ?><option value="<?= (int)$c['id'] ?>" <?= $classId===(int)$c['id']?'selected':'' ?>>Form <?= (int)$c['form_level'] ?><?= h($c['stream']) ?> · <?= (int)$c['academic_year'] ?></option><?php endforeach; ?></select></label><button class="outline-button">View class</button></form>
<?php if(!$class||!$term||(int)$class['academic_year']!==(int)$term['academic_year']): ?><div class="alert alert-warn">Choose a class and term from the same academic year.</div><?php elseif($reportStudent): ?>
<article class="report-card"><header class="report-header"><div><div class="eyebrow"><?= h($term['name']) ?> · <?= (int)$term['academic_year'] ?></div><h2><?= h($reportStudent['first_name'].' '.$reportStudent['last_name']) ?></h2><p><?= h($reportStudent['admission_no']) ?> · Form <?= (int)$class['form_level'] ?><?= h($class['stream']) ?> · <?= (int)$term['academic_year'] ?></p></div><div class="report-school"><?= h($schoolDisplayName??'School') ?><small><?= h($schoolPlace??'Zimbabwe') ?></small></div></header>
<div class="report-stat-grid"><div><small>Overall scored average</small><b><?= $overallPossible>0?number_format($overallObtained/$overallPossible*100,1).'%':'—' ?></b></div><div><small>Assessments awaiting marks</small><b><?= $missingMarks ?></b></div><div><small>Attendance recorded</small><b><?= array_sum($attendance) ?> days</b></div><div><small>Grade scale</small><b><?= $scale?h($scale['name']):'Not configured' ?></b></div></div>
<div class="table-scroll"><table class="data-table report-results"><thead><tr><th>Subject</th><th>Assessments</th><th>Marks</th><th>Percent</th><th>Grade</th><th>Descriptor</th></tr></thead><tbody><?php foreach($results as $r): ?><tr><td><b><?= h($r['subject_name']) ?></b><small class="muted-cell"><?= h($r['subject_code']) ?></small></td><td><?= (int)$r['entered_count'] ?> / <?= (int)$r['assessment_count'] ?> entered</td><td><?= $r['possible']>0?number_format($r['obtained'],2).' / '.number_format($r['possible'],2):'—' ?></td><td><?= $r['percentage']!==null?number_format($r['percentage'],1).'%':'—' ?></td><td><b><?= h($r['grade']??($r['percentage']===null?'—':'No band')) ?></b></td><td><?= h($r['band_description']?:($r['assessment_count']?'':'No assessments')) ?></td></tr><?php endforeach; if(!$results): ?><tr><td colspan="6" class="empty-cell">No subjects are assigned to this class yet.</td></tr><?php endif; ?></tbody></table></div>
<section class="report-attendance"><h3>Attendance summary</h3><div><?php foreach($attendance as $status=>$count): ?><span><b><?= $count ?></b> <?= h($status) ?></span><?php endforeach; ?></div></section>
<div class="report-comments"><section><h3>Class teacher comment</h3><p><?= nl2br(h($reportComments['teacher_comment']?:'No teacher comment recorded.')) ?></p></section><section><h3>Head of school comment</h3><p><?= nl2br(h($reportComments['head_comment']?:'No head comment recorded.')) ?></p></section></div>
<?php if($user['role']==='Teacher'&&(int)$class['class_teacher_id']===(int)$user['id']||$canManage): ?><form method="post" action="actions/report_comment_save.php" class="panel settings-panel report-comment-form no-print"><?= csrf_field() ?><input type="hidden" name="student_id" value="<?= (int)$studentId ?>"><input type="hidden" name="term_id" value="<?= (int)$termId ?>"><input type="hidden" name="class_id" value="<?= (int)$classId ?>"><h3>Save report comments</h3><label>Class teacher comment<textarea name="teacher_comment" maxlength="500" rows="3"><?= h($reportComments['teacher_comment']) ?></textarea></label><?php if($canManage): ?><label>Head of school comment<textarea name="head_comment" maxlength="500" rows="3"><?= h($reportComments['head_comment']) ?></textarea></label><?php endif; ?><button class="primary-button">Save comments</button></form><?php endif; ?>
<footer class="report-footer"><span>Prepared <?= h(date('d M Y H:i')) ?></span><span>Results reflect marks entered in the school markbook. <?= $missingMarks?'Some assessment marks are still outstanding.':'All scheduled assessment entries have a status.' ?></span></footer></article><p class="no-print"><a class="text-button" href="?page=reports&term_id=<?= (int)$termId ?>&class_id=<?= (int)$classId ?>">← Return to class list</a></p>
<?php else: ?><section class="panel learners-panel"><div class="panel-heading"><div><h2>Form <?= (int)$class['form_level'] ?><?= h($class['stream']) ?> · <?= h($term['name']) ?></h2><p>Select a learner to open a term report card. <?= count($roster) ?> learners enrolled during this term.</p></div><a class="outline-button no-print" href="actions/attendance_report_export.php?term_id=<?= (int)$termId ?>&class_id=<?= (int)$classId ?>">Download attendance CSV</a></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Learner</th><th>Admission number</th><th>Form</th><th></th></tr></thead><tbody><?php foreach($roster as $learner): ?><tr><td><b><?= h($learner['first_name'].' '.$learner['last_name']) ?></b></td><td><?= h($learner['admission_no']) ?></td><td>Form <?= (int)$class['form_level'] ?><?= h($class['stream']) ?></td><td><a class="text-button" href="?page=reports&term_id=<?= (int)$termId ?>&class_id=<?= (int)$classId ?>&student_id=<?= (int)$learner['id'] ?>">Open report →</a></td></tr><?php endforeach; if(!$roster): ?><tr><td colspan="4" class="empty-cell">No learners have an enrolment overlapping this term and class.</td></tr><?php endif; ?></tbody></table></div></section>
<section class="panel learners-panel"><div class="panel-heading"><div><h2>Attendance summary</h2><p>Totals from saved registers dated <?= h(date('d M Y',strtotime($term['starts_on']))) ?> to <?= h(date('d M Y',strtotime($term['ends_on']))) ?>.</p></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Learner</th><th>Present</th><th>Late</th><th>Absent</th><th>Excused</th><th>Recorded days</th><th>Attendance</th></tr></thead><tbody><?php foreach($attendanceRows as $ar): $present=(int)$ar['present_count'];$late=(int)$ar['late_count'];$absent=(int)$ar['absent_count'];$excused=(int)$ar['excused_count'];$denominator=$present+$late+$absent;$attendanceRate=$denominator?round(($present+$late)/$denominator*100):null; ?><tr><td><?= h($ar['first_name'].' '.$ar['last_name']) ?><small class="muted-cell"><?= h($ar['admission_no']) ?></small></td><td><?= $present ?></td><td><?= $late ?></td><td><?= $absent ?></td><td><?= $excused ?></td><td><?= $present+$late+$absent+$excused ?></td><td><?= $attendanceRate===null?'—':$attendanceRate.'%' ?></td></tr><?php endforeach; if(!$attendanceRows): ?><tr><td colspan="7" class="empty-cell">No attendance report rows for this class.</td></tr><?php endif; ?></tbody></table></div><p class="privacy-note">Attendance percentage treats Present and Late as attended and excludes Excused days from the denominator.</p></section><?php endif; ?>
<?php endif; ?>
